+START_TEST(AddMultipleTransportLayers){
+    config = UA_ServerConfig_new_default();
+
+    UA_PubSubTransportLayer pubsubTransportLayer;
+
+    ck_assert_int_eq(config->pubsubTransportLayersSize, 0);
